1	package oci
2	
3	import (
4		"archive/tar"
5		"bytes"
6		"compress/gzip"
7		"context"
8		"errors"
9		"fmt"
10		"math/rand"
11		"net/http"
12		"net/http/httptest"
13		"strings"
14		"testing"
15	)
16	
17	// DEVDESK-412 step 4: the layer blob of oci.Client follows a redirect to
18	// another origin, but never with credentials; the chain is bounded in hops and
19	// in compressed bytes, https never downgrades to http, and no error carries the
20	// (possibly signed) URL of a hop. Server A plays the registry (it serves the
21	// manifest and redirects the blob), server B the other host.
22	//
23	// The manifest and tags calls keep refusing any other origin (step 3), and
24	// those refusals are re-checked here at the end.
25	
26	const (
27		// blobSignedQuery stands for a presigned URL query; it must appear in no
28		// error and no log.
29		blobSignedQuery = "sig=SECRET"
30		// blobPrivatePath is a path that must never be echoed by an error.
31		blobPrivatePath = "/private-blob-path"
32	)
33	
34	// blobManifest is the manifest every fixture registry serves for tpl:v1.
35	func blobManifest() string {
36		return fmt.Sprintf(`{"layers":[{"mediaType":"application/vnd.oci.image.layer.v1.tar+gzip","digest":%q}]}`, clientTestDigest)
37	}
38	
39	func isManifestRequest(r *http.Request) bool {
40		return strings.Contains(r.URL.Path, "/manifests/")
41	}
42	
43	// blobRegistry starts a registry that records every request in log, serves the
44	// manifest and hands every other request to rest.
45	func blobRegistry(t *testing.T, tlsServer bool, log *hitLog, rest http.HandlerFunc) *httptest.Server {
46		t.Helper()
47		h := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
48			log.record(r)
49			if isManifestRequest(r) {
50				_, _ = fmt.Fprint(w, blobManifest())
51				return
52			}
53			rest(w, r)
54		})
55		return startServer(t, tlsServer, h)
56	}
57	
58	// archiveHost starts a host that records every request in log and serves archive
59	// to all of them.
60	func archiveHost(t *testing.T, tlsServer bool, log *hitLog, archive []byte) *httptest.Server {
61		t.Helper()
62		return startServer(t, tlsServer, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
63			log.record(r)
64			_, _ = w.Write(archive)
65		}))
66	}
67	
68	func startServer(t *testing.T, tlsServer bool, h http.Handler) *httptest.Server {
69		t.Helper()
70		var s *httptest.Server
71		if tlsServer {
72			s = httptest.NewTLSServer(h)
73		} else {
74			s = httptest.NewServer(h)
75		}
76		t.Cleanup(s.Close)
77		return s
78	}
79	
80	// withTransport sends both of the client's HTTP clients through rt, keeping the
81	// CheckRedirect each of them carries in production.
82	func withTransport(c *Client, rt http.RoundTripper) *Client {
83		c.httpClient.Transport = rt
84		c.blobClient.Transport = rt
85		return c
86	}
87	
88	// redirectTo answers every request with a 307 to loc.
89	func redirectTo(loc string) http.HandlerFunc {
90		return func(w http.ResponseWriter, r *http.Request) {
91			http.Redirect(w, r, loc, http.StatusTemporaryRedirect)
92		}
93	}
94	
95	// wantFixtureEntries checks that the download returned the one file of
96	// clientTarGz.
97	func wantFixtureEntries(t *testing.T, tpl *Template, err error) {
98		t.Helper()
99		if err != nil {
100			t.Fatalf("DownloadTemplate: %v", err)
101		}
102		if tpl == nil || len(tpl.Entries) != 1 || tpl.Entries[0].Path != "Dockerfile" ||
103			string(tpl.Entries[0].Content) != "FROM scratch\n" {
104			t.Fatalf("template = %+v, want the single Dockerfile of the fixture archive", tpl)
105		}
106	}
107	
108	// wantNoLeak fails when err mentions any of the strings a signed URL, a path or
109	// a credential would leave behind.
110	func wantNoLeak(t *testing.T, err error, leaks ...string) {
111		t.Helper()
112		for _, leak := range append(leaks, "SECRET", "sig=", clientTestPass) {
113			if strings.Contains(err.Error(), leak) {
114				t.Errorf("error %q leaks %q", err, leak)
115			}
116		}
117	}
