119	// 1. The base case: the blob goes to another origin (same host name, other
120	// port) and gets no Authorization. net/http alone would copy the header there.
121	func TestBlobRedirectOffOriginDropsCredentials(t *testing.T) {
122		var aHits, bHits hitLog
123		b := archiveHost(t, false, &bHits, clientTarGz(t))
124		a := blobRegistry(t, false, &aHits, redirectTo(b.URL+"/blob?"+blobSignedQuery))
125	
126		tpl, err := NewClient(a.URL, clientTestUser, clientTestPass).DownloadTemplate("tpl", "v1")
127	
128		wantFixtureEntries(t, tpl, err)
129		if n := bHits.count(); n != 1 {
130			t.Fatalf("the other origin received %d requests, want 1", n)
131		}
132		if got := bHits.anyAuth(); got != "" {
133			t.Errorf("the other origin saw Authorization %q, want none", got)
134		}
135		if got := authsOf(&aHits, "/manifests/"); len(got) != 1 || got[0] != basicHeader() {
136			t.Errorf("manifest Authorization = %q, want one Basic header", got)
137		}
138		if got := authsOf(&aHits, "/blobs/"); len(got) != 1 || got[0] != basicHeader() {
139			t.Errorf("registry blob Authorization = %q, want one Basic header", got)
140		}
141	}
142	
143	// 2. A subdomain of the registry host is another origin: net/http copies
144	// sensitive headers to it, the policy must not.
145	func TestBlobRedirectToSubdomainDropsCredentials(t *testing.T) {
146		var regHits, cdnHits hitLog
147		archive := clientTarGz(t)
148		var s *httptest.Server
149		s = httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
150			// One listener answers both names; the Host tells them apart.
151			if strings.HasPrefix(r.Host, "cdn.") {
152				cdnHits.record(r)
153				_, _ = w.Write(archive)
154				return
155			}
156			regHits.record(r)
157			if isManifestRequest(r) {
158				_, _ = fmt.Fprint(w, blobManifest())
159				return
160			}
161			http.Redirect(w, r, "http://cdn.registry.test:"+portOfServer(s)+"/blob?"+blobSignedQuery, http.StatusTemporaryRedirect)
162		}))
163		t.Cleanup(s.Close)
164	
165		c := withTransport(NewClient("http://registry.test:"+portOfServer(s), clientTestUser, clientTestPass), dialTo(s.Listener.Addr().String()))
166		tpl, err := c.DownloadTemplate("tpl", "v1")
167	
168		wantFixtureEntries(t, tpl, err)
169		if n := cdnHits.count(); n != 1 {
170			t.Fatalf("the subdomain received %d requests, want 1", n)
171		}
172		if got := cdnHits.anyAuth(); got != "" {
173			t.Errorf("the subdomain saw Authorization %q, want none", got)
174		}
175		if got := authsOf(&regHits, "/blobs/"); len(got) != 1 || got[0] != basicHeader() {
176			t.Errorf("registry blob Authorization = %q, want one Basic header", got)
177		}
178	}
179	
180	// 3. Once the chain left the origin, coming back to it does not bring the
181	// credentials back: A -> B -> A reaches A the second time anonymously.
182	func TestBlobRedirectCredentialsStayDroppedWhenChainReturns(t *testing.T) {
183		var aHits, bHits hitLog
184		archive := clientTarGz(t)
185		var a, b *httptest.Server
186		b = startServer(t, false, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
187			bHits.record(r)
188			http.Redirect(w, r, a.URL+"/blob-back?"+blobSignedQuery, http.StatusTemporaryRedirect)
189		}))
190		a = blobRegistry(t, false, &aHits, func(w http.ResponseWriter, r *http.Request) {
191			if strings.HasPrefix(r.URL.Path, "/blob-back") {
192				_, _ = w.Write(archive)
193				return
194			}
195			http.Redirect(w, r, b.URL+"/hop?"+blobSignedQuery, http.StatusTemporaryRedirect)
196		})
197	
198		tpl, err := NewClient(a.URL, clientTestUser, clientTestPass).DownloadTemplate("tpl", "v1")
199	
200		wantFixtureEntries(t, tpl, err)
201		if got := authsOf(&aHits, "/v2/tpl/blobs/"); len(got) != 1 || got[0] != basicHeader() {
202			t.Errorf("first registry hop Authorization = %q, want one Basic header", got)
203		}
204		if got := bHits.anyAuth(); got != "" {
205			t.Errorf("the other origin saw Authorization %q, want none", got)
206		}
207		back := authsOf(&aHits, "/blob-back")
208		if len(back) != 1 {
209			t.Fatalf("registry saw %d return requests, want 1", len(back))
210		}
211		if back[0] != "" {
212			t.Errorf("return to the registry carried Authorization %q, want none (never restored)", back[0])
213		}
214	}
215	
216	// 4. A redirect chain that stays on the registry keeps its credentials on every
217	// hop.
218	func TestBlobRedirectSameOriginChainKeepsCredentials(t *testing.T) {
219		var hits hitLog
220		archive := clientTarGz(t)
221		a := blobRegistry(t, false, &hits, func(w http.ResponseWriter, r *http.Request) {
222			switch {
223			case strings.HasPrefix(r.URL.Path, "/blob-final"):
224				_, _ = w.Write(archive)
225			case strings.HasPrefix(r.URL.Path, "/blob-moved"):
226				http.Redirect(w, r, "/blob-final", http.StatusTemporaryRedirect)
227			default:
228				http.Redirect(w, r, "/blob-moved", http.StatusTemporaryRedirect)
229			}
230		})
231	
232		tpl, err := NewClient(a.URL, clientTestUser, clientTestPass).DownloadTemplate("tpl", "v1")
233	
234		wantFixtureEntries(t, tpl, err)
235		for _, part := range []string{"/v2/tpl/blobs/", "/blob-moved", "/blob-final"} {
236			if got := authsOf(&hits, part); len(got) != 1 || got[0] != basicHeader() {
237				t.Errorf("Authorization on %s = %q, want one Basic header", part, got)
238			}
239		}
240	}
