242	// 5. A blob never goes from https to http, and may go from https to https.
243	func TestBlobRedirectDowngrade(t *testing.T) {
244		t.Run("https to http is refused", func(t *testing.T) {
245			var aHits, bHits hitLog
246			b := archiveHost(t, false, &bHits, clientTarGz(t))
247			a := blobRegistry(t, true, &aHits, redirectTo(b.URL+blobPrivatePath+"?"+blobSignedQuery))
248	
249			c := withTransport(NewClient(a.URL, clientTestUser, clientTestPass), a.Client().Transport)
250			tpl, err := c.DownloadTemplate("tpl", "v1")
251	
252			if !errors.Is(err, errInsecureRedirect) {
253				t.Fatalf("err = %v, want errors.Is errInsecureRedirect", err)
254			}
255			if tpl != nil {
256				t.Errorf("template = %+v, want nil", tpl)
257			}
258			if n := bHits.count(); n != 0 {
259				t.Errorf("the http target received %d requests, want 0", n)
260			}
261			wantNoLeak(t, err, blobPrivatePath)
262		})
263	
264		t.Run("https to https is followed without credentials", func(t *testing.T) {
265			var aHits, bHits hitLog
266			b := archiveHost(t, true, &bHits, clientTarGz(t))
267			a := blobRegistry(t, true, &aHits, redirectTo(b.URL+"/blob?"+blobSignedQuery))
268	
269			// Both TLS test servers share one certificate.
270			c := withTransport(NewClient(a.URL, clientTestUser, clientTestPass), a.Client().Transport)
271			tpl, err := c.DownloadTemplate("tpl", "v1")
272	
273			wantFixtureEntries(t, tpl, err)
274			if n := bHits.count(); n != 1 {
275				t.Fatalf("the https target received %d requests, want 1", n)
276			}
277			if got := bHits.anyAuth(); got != "" {
278				t.Errorf("the https target saw Authorization %q, want none", got)
279			}
280		})
281	
282		t.Run("http to https is followed", func(t *testing.T) {
283			var aHits, bHits hitLog
284			b := archiveHost(t, true, &bHits, clientTarGz(t))
285			a := blobRegistry(t, false, &aHits, redirectTo(b.URL+"/blob?"+blobSignedQuery))
286	
287			c := withTransport(NewClient(a.URL, clientTestUser, clientTestPass), b.Client().Transport)
288			tpl, err := c.DownloadTemplate("tpl", "v1")
289	
290			wantFixtureEntries(t, tpl, err)
291			if got := bHits.anyAuth(); got != "" {
292				t.Errorf("the https target saw Authorization %q, want none", got)
293			}
294		})
295	}
