297	// 6. The chain is bounded: A and B keep redirecting to each other and the
298	// download stops after MaxRedirects hops, without any hop's URL in the error.
299	func TestBlobRedirectChainIsBounded(t *testing.T) {
300		var aHits, bHits hitLog
301		var a, b *httptest.Server
302		hop := func(other func() string, log *hitLog) http.HandlerFunc {
303			return func(w http.ResponseWriter, r *http.Request) {
304				log.record(r)
305				n := log.count()
306				http.Redirect(w, r, fmt.Sprintf("%s/hop%d-SECRET?%s", other(), n, blobSignedQuery), http.StatusTemporaryRedirect)
307			}
308		}
309		b = startServer(t, false, hop(func() string { return a.URL }, &bHits))
310		a = blobRegistry(t, false, &aHits, hop(func() string { return b.URL }, &aHits))
311	
312		tpl, err := NewClient(a.URL, clientTestUser, clientTestPass).DownloadTemplate("tpl", "v1")
313	
314		if !errors.Is(err, ErrTooManyRedirects) {
315			t.Fatalf("err = %v, want errors.Is ErrTooManyRedirects", err)
316		}
317		if tpl != nil {
318			t.Errorf("template = %+v, want nil", tpl)
319		}
320		if !strings.Contains(err.Error(), "stopped after 10 redirects") {
321			t.Errorf("error %q lacks the cap message", err)
322		}
323		// The manifest is one request of A; the rest is the blob chain.
324		if n := aHits.count() - 1 + bHits.count(); n != MaxRedirects {
325			t.Errorf("blob chain made %d requests, want %d", n, MaxRedirects)
326		}
327		wantNoLeak(t, err, "/hop")
328	}
