330	// 7. A transport failure on the other host names that host at most: not the
331	// path, not the signed query.
332	func TestBlobTransportErrorCarriesNoSignedURL(t *testing.T) {
333		var aHits, bHits hitLog
334		b := startServer(t, false, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
335			bHits.record(r)
336			// Drop the connection with no response at all.
337			conn, _, err := w.(http.Hijacker).Hijack()
338			if err != nil {
339				t.Errorf("hijack: %v", err)
340				return
341			}
342			_ = conn.Close()
343		}))
344		a := blobRegistry(t, false, &aHits, redirectTo(b.URL+blobPrivatePath+"?"+blobSignedQuery))
345	
346		tpl, err := NewClient(a.URL, clientTestUser, clientTestPass).DownloadTemplate("tpl", "v1")
347	
348		if err == nil {
349			t.Fatalf("template = %+v, want an error", tpl)
350		}
351		if bHits.count() == 0 {
352			t.Fatal("the other host was never reached, the test checks nothing")
353		}
354		wantNoLeak(t, err, blobPrivatePath, "http://")
355	}
