357	// paddedTarGz builds a small archive of three tiny files, each preceded by a
358	// PAX header carrying 500 KiB of seeded random (incompressible) padding. The
359	// padding is neither file content nor counted by Limits, so only a cap on the
360	// bytes taken off the network sees it: about 1.5 MiB in all.
361	func paddedTarGz(t *testing.T) []byte {
362		t.Helper()
363		const (
364			files   = 3
365			padSize = 500 << 10
366		)
367		rng := rand.New(rand.NewSource(412))
368		var buf bytes.Buffer
369		gzw := gzip.NewWriter(&buf)
370		tw := tar.NewWriter(gzw)
371		for i := range files {
372			pad := make([]byte, padSize)
373			_, _ = rng.Read(pad)
374			hdr := &tar.Header{
375				Name:       fmt.Sprintf("f%d.txt", i),
376				Mode:       0o644,
377				Size:       2,
378				Typeflag:   tar.TypeReg,
379				Format:     tar.FormatPAX,
380				PAXRecords: map[string]string{"DEVDESK.pad": string(pad)},
381			}
382			if err := tw.WriteHeader(hdr); err != nil {
383				t.Fatalf("writing header %d: %v", i, err)
384			}
385			if _, err := tw.Write([]byte("hi")); err != nil {
386				t.Fatalf("writing body %d: %v", i, err)
387			}
388		}
389		if err := tw.Close(); err != nil {
390			t.Fatalf("closing tar: %v", err)
391		}
392		if err := gzw.Close(); err != nil {
393			t.Fatalf("closing gzip: %v", err)
394		}
395		if buf.Len() > 2<<20 {
396			t.Fatalf("fixture is %d bytes, keep it under 2 MiB", buf.Len())
397		}
398		return buf.Bytes()
399	}
400	
401	// 8. The compressed bytes taken off the network are capped, even when what the
402	// archive declares as content stays within Limits.
403	func TestBlobByteCap(t *testing.T) {
404		archive := paddedTarGz(t)
405		lim := Limits{Files: 10, Bytes: 1 << 10}
406		if int64(len(archive)) <= blobCap(lim) {
407			t.Fatalf("fixture (%d bytes) is not over blobCap (%d), the test checks nothing", len(archive), blobCap(lim))
408		}
409	
410		t.Run("blobCap formula", func(t *testing.T) {
411			if got, want := blobCap(lim), int64(1<<10+10*2048+1<<20); got != want {
412				t.Errorf("blobCap(%+v) = %d, want %d", lim, got, want)
413			}
414			if got := blobCap(Limits{}); got != 0 {
415				t.Errorf("blobCap(zero) = %d, want 0 (no cap)", got)
416			}
417		})
418	
419		t.Run("redirected blob over the cap", func(t *testing.T) {
420			var aHits, bHits hitLog
421			b := archiveHost(t, false, &bHits, archive)
422			a := blobRegistry(t, false, &aHits, redirectTo(b.URL+"/blob?"+blobSignedQuery))
423	
424			c := NewClient(a.URL, clientTestUser, clientTestPass)
425			c.Limits = lim
426			tpl, err := c.DownloadTemplate("tpl", "v1")
427	
428			if !errors.Is(err, ErrArchiveTooLarge) {
429				t.Fatalf("err = %v, want errors.Is ErrArchiveTooLarge", err)
430			}
431			if tpl != nil {
432				t.Errorf("template = %+v, want nil", tpl)
433			}
434		})
435	
436		t.Run("same archive without limits is read", func(t *testing.T) {
