357	// paddedTarGz builds a small archive of three tiny files, each preceded by a
358	// PAX header carrying 500 KiB of seeded random (incompressible) padding. The
359	// padding is neither file content nor counted by Limits, so only a cap on the
360	// bytes taken off the network sees it: about 1.5 MiB in all.
361	func paddedTarGz(t *testing.T) []byte {
362		t.Helper()
363		const (
364			files   = 3
365			padSize = 500 << 10
366		)
367		rng := rand.New(rand.NewSource(412))
368		var buf bytes.Buffer
369		gzw := gzip.NewWriter(&buf)
370		tw := tar.NewWriter(gzw)
371		for i := range files {
372			pad := make([]byte, padSize)
373			_, _ = rng.Read(pad)
374			hdr := &tar.Header{
375				Name:       fmt.Sprintf("f%d.txt", i),
376				Mode:       0o644,
377				Size:       2,
378				Typeflag:   tar.TypeReg,
379				Format:     tar.FormatPAX,
380				PAXRecords: map[string]string{"DEVDESK.pad": string(pad)},
381			}
