205	// 3c. followBlobRedirect called directly: limits, schemes, previous-hop
206	// downgrade, sticky credential removal and Referer removal.
207	func TestFollowBlobRedirect(t *testing.T) {
208		const reg = "http://registry.test:5000/v2/tpl/blobs/sha256:abc"
209		const regTLS = "https://registry.test/v2/tpl/blobs/sha256:abc"
210		tenHops := make([]string, MaxRedirects)
211		for i := range tenHops {
212			tenHops[i] = reg
213		}
214	
215		cases := []struct {
216			name string
217			via  []string
218			to   string
219			want error // nil = followed
220			// keepAuth is whether Authorization must survive when the redirect is
221			// followed.
222			keepAuth bool
223		}{
224			{"too many hops", tenHops, "http://registry.test:5000/next", ErrTooManyRedirects, false},
225			{"one hop short of the cap", tenHops[:MaxRedirects-1], "http://registry.test:5000/next", nil, true},
226			{"ftp", []string{reg}, "ftp://files.example/p/SECRET?sig=SECRET", errBlobRedirectScheme, false},
227			{"file", []string{reg}, "file:///etc/passwd", errBlobRedirectScheme, false},
228			{"no scheme", []string{reg}, "//files.example/p/SECRET?sig=SECRET", errBlobRedirectScheme, false},
229			{"https to http", []string{regTLS}, "http://cdn.example/p/SECRET?sig=SECRET", errInsecureRedirect, false},
230			{"http, https, then http", []string{reg, "https://cdn.example/hop"}, "http://other.example/p/SECRET?sig=SECRET", errInsecureRedirect, false},
231			{"https, https, then http", []string{regTLS, "https://cdn.example/hop"}, "http://other.example/p/SECRET?sig=SECRET", errInsecureRedirect, false},
232			{"https, https, then https", []string{regTLS, "https://cdn.example/hop"}, "https://other.example/p", nil, false},
233			{"http, https, then https", []string{reg, "https://cdn.example/hop"}, "https://other.example/p", nil, false},
234			{"http, http, then http", []string{reg, "http://cdn.example/hop"}, "http://other.example/p", nil, false},
235			{"same origin keeps credentials", []string{reg}, "http://registry.test:5000/elsewhere", nil, true},
236			{"same origin chain keeps credentials", []string{reg, "http://registry.test:5000/a"}, "http://registry.test:5000/b", nil, true},
237			{"other host", []string{reg}, "http://cdn.example/p", nil, false},
238			{"other port", []string{reg}, "http://registry.test:5001/p", nil, false},
239			{"subdomain", []string{reg}, "http://cdn.registry.test:5000/p", nil, false},
240			{"scheme change on the same host", []string{reg}, "https://registry.test:5000/p", nil, false},
241			{"back to the origin after leaving it", []string{reg, "http://cdn.example/hop"}, "http://registry.test:5000/back", nil, false},
242		}
243		for _, tc := range cases {
244			t.Run(tc.name, func(t *testing.T) {
245				via := make([]*http.Request, len(tc.via))
246				for i, v := range tc.via {
247					via[i] = mustReq(t, v)
248				}
249				req := mustReq(t, tc.to)
250				req.SetBasicAuth(clientTestUser, clientTestPass)
251				req.Header.Set("Referer", reg+"?"+blobSignedQuery)
252	
253				err := followBlobRedirect(req, via)
254	
255				if tc.want == nil {
256					if err != nil {
257						t.Fatalf("followBlobRedirect = %v, want nil", err)
258					}
259				} else {
260					if !errors.Is(err, tc.want) {
261						t.Fatalf("followBlobRedirect = %v, want errors.Is %v", err, tc.want)
262					}
263					if strings.Contains(err.Error(), "SECRET") || strings.Contains(err.Error(), "/p/") {
264						t.Errorf("error %q carries the target's path or query", err)
265					}
266					return
267				}
268				if got := req.Header.Get("Authorization") != ""; got != tc.keepAuth {
269					t.Errorf("Authorization kept = %v, want %v", got, tc.keepAuth)
270				}
271				if !sameOrigin(tc.via[0], tc.to) {
272					if got := req.Header.Get("Referer"); got != "" {
273						t.Errorf("Referer = %q after leaving the origin, want none", got)
274					}
275				}
276			})
277		}
278	}
