280	// 4d. The control is wired into the transport NewClient gives the blob client:
281	// for a registry that is not local the transport cannot connect to a live
282	// loopback listener, for a local registry it can.
283	func TestNewClientBlobTransportRefusesLocalUnlessRegistryIsLocal(t *testing.T) {
284		ln, err := net.Listen("tcp", "127.0.0.1:0")
285		if err != nil {
286			t.Fatal(err)
287		}
288		t.Cleanup(func() { _ = ln.Close() })
289		// The listener stays open for the whole test: a refusal can only come
290		// from the client, never from a closed port.
291	
292		dial := func(t *testing.T, registryURL string) error {
293			t.Helper()
294			tr, ok := NewClient(registryURL, "", "").blobClient.Transport.(*http.Transport)
295			if !ok || tr.DialContext == nil {
296				t.Fatalf("blobClient.Transport = %T, want an *http.Transport with a DialContext", NewClient(registryURL, "", "").blobClient.Transport)
297			}
298			conn, err := tr.DialContext(context.Background(), "tcp", ln.Addr().String())
299			if err == nil {
300				_ = conn.Close()
301			}
302			return err
303		}
304	
305		if err := dial(t, "https://registry.example.com"); err == nil {
306			t.Error("blob transport of a public registry connected to a loopback address, want a refusal")
307		}
308		for _, local := range []string{"http://127.0.0.1:5000", "http://localhost:5000", "http://[::1]:5000"} {
309			if err := dial(t, local); err != nil {
310				t.Errorf("blob transport of the local registry %s refused a loopback address: %v", local, err)
311			}
312		}
313	}
