315	// statusRoundTripper answers every request with a response whose raw Status
316	// line is whatever a hostile server chose to write.
317	type statusRoundTripper struct {
318		code   int
319		status string
320	}
321	
322	func (s statusRoundTripper) RoundTrip(req *http.Request) (*http.Response, error) {
323		return &http.Response{
324			StatusCode: s.code,
325			Status:     s.status,
326			Header:     http.Header{},
327			Body:       http.NoBody,
328			Request:    req,
329		}, nil
330	}
331	
332	func wantPlainStatusError(t *testing.T, err error, code int) {
333		t.Helper()
334		if err == nil {
335			t.Fatal("err = nil, want a failure")
336		}
337		for _, r := range err.Error() {
338			if unicode.IsControl(r) {
339				t.Errorf("error %q holds the control character %U", err, r)
340			}
341		}
342		if strings.Contains(err.Error(), "Evil") {
343			t.Errorf("error %q repeats the raw status text of the server", err)
344		}
345		if want := fmt.Sprintf("%d %s", code, http.StatusText(code)); !strings.Contains(err.Error(), want) {
346			t.Errorf("error %q lacks %q", err, want)
347		}
348	}
