28	// headerLog records, for each request, its Referer and a dump of all its headers.
29	type headerLog struct {
30		mu       sync.Mutex
31		referers []string
32		dumps    []string
33	}
34	
35	func (l *headerLog) record(r *http.Request) {
36		l.mu.Lock()
37		defer l.mu.Unlock()
38		l.referers = append(l.referers, r.Header.Get("Referer"))
39		l.dumps = append(l.dumps, fmt.Sprint(r.Header))
40	}
41	
42	func (l *headerLog) all() (referers, dumps []string) {
43		l.mu.Lock()
44		defer l.mu.Unlock()
45		return append([]string(nil), l.referers...), append([]string(nil), l.dumps...)
46	}
