48	// dialRouted sends the connections for a ".test" name to def and every other
49	// connection where it was asked to go. A literal address therefore reaches its
50	// own server, so a redirect that is not refused is visible in that server's log.
51	func dialRouted(def string) *http.Transport {
52		byName := dialTo(def)
53		direct := &net.Dialer{}
54		byName.DialContext = func(ctx context.Context, network, addr string) (net.Conn, error) {
55			host, _, err := net.SplitHostPort(addr)
56			if err == nil && strings.HasSuffix(host, ".test") {
57				return direct.DialContext(ctx, network, def)
58			}
59			return direct.DialContext(ctx, network, addr)
60		}
61		return byName
62	}
