64	// 1. A chain A -> B -> C: no hop receives a Referer, and the signed URL of B
65	// never reaches C.
66	func TestBlobRedirectChainSendsNoReferer(t *testing.T) {
67		var aLog, bLog, cLog headerLog
68		archive := clientTarGz(t)
69	
70		c := startServer(t, false, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
71			cLog.record(r)
72			_, _ = w.Write(archive)
73		}))
74		b := startServer(t, false, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
75			bLog.record(r)
76			http.Redirect(w, r, c.URL+"/final?sig=OTHER", http.StatusTemporaryRedirect)
77		}))
78		a := startServer(t, false, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
79			aLog.record(r)
80			if isManifestRequest(r) {
81				_, _ = fmt.Fprint(w, blobManifest())
82				return
83			}
84			http.Redirect(w, r, b.URL+"/hop?"+blobSignedQuery, http.StatusTemporaryRedirect)
85		}))
86	
87		tpl, err := NewClient(a.URL, clientTestUser, clientTestPass).DownloadTemplate("tpl", "v1")
88	
89		wantFixtureEntries(t, tpl, err)
90		for name, l := range map[string]*headerLog{"B": &bLog, "C": &cLog} {
91			referers, dumps := l.all()
92			if len(referers) != 1 {
93				t.Fatalf("%s received %d requests, want 1", name, len(referers))
94			}
95			if referers[0] != "" {
96				t.Errorf("%s received Referer %q, want none", name, referers[0])
97			}
98			for _, d := range dumps {
99				if strings.Contains(d, blobSignedQuery) || strings.Contains(d, "/hop") {
100					t.Errorf("%s received headers carrying a previous hop's URL: %s", name, d)
101				}
102			}
103		}
104	}
