106	// 2. The https to http check compares with the previous hop: a chain that
107	// started on http, went up to https and tries to come back down to http is
108	// refused. A chain that stays on https is followed.
109	func TestBlobRedirectDowngradeComparesWithPreviousHop(t *testing.T) {
110		t.Run("http to https to http is refused", func(t *testing.T) {
111			var aHits, bHits, cHits hitLog
112			cHost := archiveHost(t, false, &cHits, clientTarGz(t))
113			b := startServer(t, true, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
114				bHits.record(r)
115				http.Redirect(w, r, cHost.URL+blobPrivatePath+"?"+blobSignedQuery, http.StatusTemporaryRedirect)
116			}))
117			a := blobRegistry(t, false, &aHits, redirectTo(b.URL+"/hop?"+blobSignedQuery))
118	
119			// b's certificate is the one every httptest TLS server shares; its
120			// transport also speaks plain http.
121			c := withTransport(NewClient(a.URL, clientTestUser, clientTestPass), b.Client().Transport)
122			tpl, err := c.DownloadTemplate("tpl", "v1")
123	
124			if !errors.Is(err, errInsecureRedirect) {
125				t.Fatalf("err = %v, want errors.Is errInsecureRedirect", err)
126			}
127			if tpl != nil {
128				t.Errorf("template = %+v, want nil", tpl)
129			}
130			if n := bHits.count(); n != 1 {
131				t.Errorf("the https hop received %d requests, want 1", n)
132			}
133			if n := cHits.count(); n != 0 {
134				t.Errorf("the http target received %d requests, want 0", n)
135			}
136			wantNoLeak(t, err, blobPrivatePath, "/hop")
137		})
