139		t.Run("https to https to https is followed", func(t *testing.T) {
140			var aHits, bHits, cHits hitLog
141			cHost := archiveHost(t, true, &cHits, clientTarGz(t))
142			b := startServer(t, true, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
143				bHits.record(r)
144				http.Redirect(w, r, cHost.URL+"/final?"+blobSignedQuery, http.StatusTemporaryRedirect)
145			}))
146			a := blobRegistry(t, true, &aHits, redirectTo(b.URL+"/hop?"+blobSignedQuery))
147	
148			c := withTransport(NewClient(a.URL, clientTestUser, clientTestPass), a.Client().Transport)
149			tpl, err := c.DownloadTemplate("tpl", "v1")
150	
151			wantFixtureEntries(t, tpl, err)
152			if bHits.anyAuth() != "" || cHits.anyAuth() != "" {
